name: Auto-triage new issues
on:
  issues:
    types: [opened]
permissions:
  issues: write
jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Auto-triage issue
        uses: actions/github-script@v6
        with:
          script: |
            const issue = context.payload.issue;
            const title = issue.title.toLowerCase();
            const body = (issue.body || '').toLowerCase();
            const text = title + ' ' + body;

            const bugKeywords = ['bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'];
            const featureKeywords = ['feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve'];
            const highKeywords = ['critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'];
            const lowKeywords = ['minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4'];

            let typeLabel = 'feature-request';
            for (const kw of bugKeywords) {
              if (text.includes(kw)) { typeLabel = 'bug'; break; }
            }
            if (typeLabel !== 'bug') {
              for (const kw of featureKeywords) {
                if (text.includes(kw)) { typeLabel = 'feature-request'; break; }
              }
            }

            let priorityLabel = 'priority: medium';
            for (const kw of highKeywords) {
              if (text.includes(kw)) { priorityLabel = 'priority: high'; break; }
            }
            if (priorityLabel === 'priority: medium') {
              for (const kw of lowKeywords) {
                if (text.includes(kw)) { priorityLabel = 'priority: low'; break; }
              }
            }

            const labelsToAdd = [typeLabel, priorityLabel];

            const existingLabels = await github.paginate(github.issues.listLabelsForRepo, {
              owner: context.repo.owner,
              repo: context.repo.repo,
            });

            const existingLabelNames = existingLabels.map(l => l.name);

            const labelColors = {
              'bug': 'd73a4a',
              'feature-request': '0e8a16',
              'priority: high': 'd73a4a',
              'priority: medium': 'f9d0c4',
              'priority: low': '0e8a16',
            };

            for (const label of labelsToAdd) {
              if (!existingLabelNames.includes(label)) {
                await github.issues.createLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label,
                  color: labelColors[label] || 'ffffff',
                });
              }
            }

            await github.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              labels: labelsToAdd,
            });
